        "run": "set -euo pipefail\n# One writer for all three outputs, so this job cannot publish a `code` its\n# `reason` contradicts, or a `legs` its `code` contradicts. The fan-in checks\n# the three against each other; that check is only worth making because they\n# are written here, together, once.\nemit() { # <code> <reason>\n  legs=all\n  if [ \"$1\" = \"false\" ]; then legs=none; fi\n  {\n    echo \"code=$1\"\n    echo \"reason=$2\"\n    echo \"legs=$legs\"\n  } >> \"$GITHUB_OUTPUT\"\n  echo \"scope: code=$1, legs=$legs, reason=$2\"\n}\nif [ -z \"${PR_NUMBER:-}\" ]; then\n  echo \"no pull request in this context (event: $EVENT_NAME) — running every gate\"\n  emit true no-pr-context\n  exit 0\nfi\nfiles_json=\"${RUNNER_TEMP:-/tmp}/pr-files.json\"\npr_json=\"${RUNNER_TEMP:-/tmp}/pr-object.json\"\npr=\"repos/${REPOSITORY}/pulls/${PR_NUMBER}\"\ngh api --paginate --slurp \"$pr/files\" >\"$files_json\" 2>/dev/null || : >\"$files_json\"\ngh api \"$pr\" >\"$pr_json\" 2>/dev/null || : >\"$pr_json\"\nif [ ! -s \"$files_json\" ] || [ ! -s \"$pr_json\" ]; then\n  echo \"could not read the PR from the API — running every gate\"\n  emit true api-unreadable\n  exit 0\nfi\necho \"changed paths (name, then previous name for renames):\"\njq -r '.[][] | \"  \" + (.filename|tojson) + (if .previous_filename == null then \"\" else \"  <- \" + (.previous_filename|tojson) end)' \\\n  \"$files_json\" 2>/dev/null || echo \"  (unparseable — pr-scope will fail closed)\"\n# Same polarity as ever: only the one string this script writes on purpose\n# buys a skip. A non-zero exit, an empty answer, or any word nobody\n# anticipated all land on \"run every gate\".\ncode=\"$(bash scripts/ci/pr-scope.sh \"$files_json\" \"$pr_json\")\" || code=nonzero-exit\ncase \"$code\" in\n  false)\n    echo \"docs/** only, and the file list is provably complete — every gate below is a no-op\"\n    emit false docs-only\n    ;;\n  true) emit true outside-docs ;;\n  *) emit true scope-script-failed ;;\nesac\n"
      }
    ],
    "timeout-minutes": 10
  },
  "tests": {
    "if": "needs.scope.outputs.code != 'false'",
    "name": "tests",
    "needs": "scope",
    "runs-on": "ubuntu-latest",
    "services": {
      "postgres": {
        "env": {
          "POSTGRES_DB": "fikirtive_test",
          "POSTGRES_PASSWORD": "postgres",
          "POSTGRES_USER": "postgres"
        },
        "image": "postgres:16",
        "options": "--health-cmd pg_isready --health-interval 10s --health-timeout 5s --health-retries 5",
        "ports": [
          "5432:5432"
        ]
      }
    },
    "steps": [
      {
        "uses": "actions/checkout@v4"
      },
      {
        "name": "ci.yml is the reviewed one",
        "run": "set -eu\nwant=\"$(cut -d' ' -f1 .github/ci-workflow.lock)\"\ngot=\"$(sha256sum .github/workflows/ci.yml | cut -d' ' -f1)\"\n[ ${#want} -eq 64 ] || { echo \"ci-guard: .github/ci-workflow.lock does not hold one sha256 digest\"; exit 1; }\n[ \"$want\" = \"$got\" ] || { echo \"ci-guard: ci.yml is $got, .github/ci-workflow.lock pins $want. If the change to ci.yml was intended, regenerate the lock in the SAME commit: bash scripts/ci/ci-workflow-lock.sh\"; exit 1; }\nfor f in .npmrc .pnpmfile.cjs apps/*/.npmrc apps/*/.pnpmfile.cjs packages/*/.npmrc packages/*/.pnpmfile.cjs; do\n  [ ! -e \"$f\" ] || { echo \"ci-guard: $f is in this checkout, and pnpm reads it before any gate does. #874 r12: 'script-shell=/bin/echo' in .npmrc makes every 'pnpm quality --leg <leg>' print its own command and exit 0, and .pnpmfile.cjs is JavaScript pnpm runs during install. Neither file existed when this ratchet was written. If adding one is intended, say so by editing this step in ci.yml AND its hand-written copy in scripts/__tests__/quality-legs.test.sh, in the SAME commit.\"; exit 1; }\ndone\necho \"ci-guard: ci.yml matches .github/ci-workflow.lock ($got), and no .npmrc/.pnpmfile.cjs is in this checkout\"\n",
        "shell": "sh"
      },
      {
        "uses": "pnpm/action-setup@v4"
      },
      {
        "uses": "actions/setup-node@v4",
        "with": {
          "cache": "pnpm",
          "node-version": 22
        }
      },
      {
        "run": "pnpm install --frozen-lockfile"
      },
      {
        "run": "pnpm quality --leg tests"
      }
    ],
    "timeout-minutes": 30
  },
  "typecheck": {
    "if": "needs.scope.outputs.code != 'false'",
    "name": "typecheck",
    "needs": "scope",
    "runs-on": "ubuntu-latest",
    "services": {
      "postgres": {
        "env": {
          "POSTGRES_DB": "fikirtive_test",
          "POSTGRES_PASSWORD": "postgres",
          "POSTGRES_USER": "postgres"
        },
        "image": "postgres:16",
        "options": "--health-cmd pg_isready --health-interval 10s --health-timeout 5s --health-retries 5",
        "ports": [
          "5432:5432"
        ]
      }
    },
    "steps": [
      {
        "uses": "actions/checkout@v4"
      },
      {
        "name": "ci.yml is the reviewed one",
        "run": "set -eu\nwant=\"$(cut -d' ' -f1 .github/ci-workflow.lock)\"\ngot=\"$(sha256sum .github/workflows/ci.yml | cut -d' ' -f1)\"\n[ ${#want} -eq 64 ] || { echo \"ci-guard: .github/ci-workflow.lock does not hold one sha256 digest\"; exit 1; }\n[ \"$want\" = \"$got\" ] || { echo \"ci-guard: ci.yml is $got, .github/ci-workflow.lock pins $want. If the change to ci.yml was intended, regenerate the lock in the SAME commit: bash scripts/ci/ci-workflow-lock.sh\"; exit 1; }\nfor f in .npmrc .pnpmfile.cjs apps/*/.npmrc apps/*/.pnpmfile.cjs packages/*/.npmrc packages/*/.pnpmfile.cjs; do\n  [ ! -e \"$f\" ] || { echo \"ci-guard: $f is in this checkout, and pnpm reads it before any gate does. #874 r12: 'script-shell=/bin/echo' in .npmrc makes every 'pnpm quality --leg <leg>' print its own command and exit 0, and .pnpmfile.cjs is JavaScript pnpm runs during install. Neither file existed when this ratchet was written. If adding one is intended, say so by editing this step in ci.yml AND its hand-written copy in scripts/__tests__/quality-legs.test.sh, in the SAME commit.\"; exit 1; }\ndone\necho \"ci-guard: ci.yml matches .github/ci-workflow.lock ($got), and no .npmrc/.pnpmfile.cjs is in this checkout\"\n",
        "shell": "sh"
      },
      {
        "uses": "pnpm/action-setup@v4"
      },
      {
        "uses": "actions/setup-node@v4",
        "with": {
          "cache": "pnpm",
          "node-version": 22
        }
      },
      {
        "run": "pnpm install --frozen-lockfile"
      },
      {
        "name": "Restore the tsc incremental state",
        "uses": "actions/cache@v4",
        "with": {
          "key": "tsbuildinfo-${{ runner.os }}-node22-${{ hashFiles('pnpm-lock.yaml') }}-${{ github.sha }}",
          "path": "apps/web/tsconfig.tsbuildinfo",
          "restore-keys": "tsbuildinfo-${{ runner.os }}-node22-${{ hashFiles('pnpm-lock.yaml') }}-\ntsbuildinfo-${{ runner.os }}-node22-\n"
        }
      },
      {
        "run": "pnpm quality --leg typecheck"
      }
    ],
    "timeout-minutes": 30
  }
}
QUALITY_LEGS_JOBS_CANONICAL_EOF
)"

canonical_compare() {
  local what="$1" want="$2" got="$3"
  if [[ "$want" == "$got" ]]; then return 0; fi
  echo "quality-legs: ci.yml's $what is not what this file pins, byte for byte" >&2
  echo "  (- is the literal in scripts/__tests__/quality-legs.test.sh, + is ci.yml as parsed by $yaml_parser)" >&2
  diff <(printf '%s\n' "$want") <(printf '%s\n' "$got") >&2 || true
  fail "ci.yml changed and the canonical block in this file did not. If the change was intended, regenerate the block (QUALITY_LEGS_PRINT_CANONICAL=1 bash scripts/__tests__/quality-legs.test.sh), read the diff, and paste it in THE SAME COMMIT — and restate anything the diagnostics above name, so the intent is written down twice by a human and not once by a parser"
}

canonical_compare "everything above 'jobs:'" "$expected_toplevel_canonical" "$actual_toplevel_canonical"
canonical_compare "'jobs:' block" "$expected_jobs_canonical" "$actual_jobs_canonical"

# ── 4. the router ─────────────────────────────────────────────────────────────
# The real function, extracted from the real file — a copy in this test would
# drift and then prove nothing.
router="$(sed -n '/^gate_runs_here() {/,/^}$/p' "$quality_sh")"
[[ -n "$router" ]] || fail "could not extract gate_runs_here() from quality.sh"

router_says() {
  # subshell: quality_leg is set per case and must not leak into the next one
  (
    quality_leg="$1"
    eval "$router"
    gate_runs_here "$2"
  )
}

expect_router() {
  local leg="$1" legs="$2" want="$3"
  if router_says "$leg" "$legs"; then
    [[ "$want" == "runs" ]] || fail "router: leg='$leg' gate legs='$legs' ran, expected skip"
  else
    [[ "$want" == "skips" ]] || fail "router: leg='$leg' gate legs='$legs' was skipped, expected run"
  fi
}

# No leg selected — the local default — runs everything, including gates whose
# leg field nobody would ever pass on the command line.
expect_router "" "typecheck" runs
expect_router "" "all" runs
expect_router "" "tests,checks" runs
# A selected leg takes its own gates, the shared ones, and nothing else.
expect_router "typecheck" "typecheck" runs
expect_router "typecheck" "all" runs
expect_router "typecheck" "tests" skips
expect_router "checks" "tests,checks" runs
expect_router "tests" "tests,checks" runs
expect_router "build" "tests,checks" skips
# Substrings must not match: a leg named `test` must never collect the `tests`
# gates, and the comma list is a set of whole names, not a haystack.
expect_router "test" "tests" skips
expect_router "check" "tests,checks" skips
expect_router "all" "typecheck" skips

echo "quality-legs: OK — all $gate_count expected gates are in quality.sh on their expected legs, legs [${declared_legs[*]}] all covered there and all launched by ci.yml by a job that runs that leg's command and nothing else, the fan-in check 'quality' judges each leg by name exactly once (its own script run here against every way a leg can come back un-green), all $jobs_with_tripwire jobs open with the checkout and then the tripwire this file pins by hand (and $lock_rel is current: $workflow_digest), the fan-in re-derives the docs-only answer for itself in the step this file also pins by hand and refuses a skip it cannot reproduce, ci.yml names exactly the ${#expected_workflow_scripts[@]} repository scripts written out here, and ci.yml as a whole — every job, step, key and value of it — is byte for byte the workflow pinned in section 3e (read as YAML with ${#parser_labels[@]} parser(s) on this machine, all agreeing: ${parser_labels[*]}). What this does NOT prove is in the header: it all runs inside one leg, and the tripwire in ci.yml is what holds when that leg is switched off."
